<script setup lang="ts">
import{Head,Link,useForm}from'@inertiajs/vue3';import EmptyState from'../../Components/Feedback/EmptyState.vue';import Pagination from'../../Components/Navigation/Pagination.vue';import AppLayout from'../../Layouts/AppLayout.vue';import{useStoreDateTime}from'../../composables/useStoreDateTime';interface Row{id:number;sku:string|null;tracked:boolean;shopify_inventory_item_id:string;available_total:number|null;levels_count:number;synced_at:string|null;variant:{title:string;product:{title:string;handle:string}|null}|null}interface P<T>{data:T[];links:Array<{url:string|null;label:string;active:boolean}>}const props=defineProps<{inventory:P<Row>;filters:{search?:string;tracked?:string}}>();const form=useForm({search:props.filters.search??'',tracked:props.filters.tracked??''});const submit=()=>form.get('/inventory',{preserveState:true,replace:true});const{formatDateTime:date}=useStoreDateTime();
</script>
<template><Head title="库存管理"/><AppLayout :breadcrumbs="[{label:'工作台',href:'/dashboard'},{label:'业务中心'},{label:'库存管理'}]"><div class="mx-auto max-w-7xl space-y-6"><header><p class="text-sm font-semibold text-emerald-700">Shopify 库存</p><h1 class="mt-1 text-3xl font-semibold text-slate-950">库存管理</h1><p class="mt-2 text-sm text-slate-500">按商品变体和地点查看当前店铺可用库存。</p></header><form class="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-[minmax(0,1fr)_180px_auto]" @submit.prevent="submit"><input v-model="form.search" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm" placeholder="搜索商品、变体或 SKU"/><select v-model="form.tracked" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm"><option value="">全部库存</option><option value="1">跟踪库存</option><option value="0">不跟踪</option></select><button class="rounded-xl bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white">筛选</button></form><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div v-if="inventory.data.length" class="overflow-x-auto"><table class="w-full min-w-[920px] text-left text-sm"><thead class="border-b border-slate-200 bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-4">商品 / 变体</th><th class="px-5 py-4">SKU</th><th class="px-5 py-4">跟踪</th><th class="px-5 py-4">可用库存</th><th class="px-5 py-4">地点</th><th class="px-5 py-4">最近同步</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in inventory.data" :key="item.id" class="hover:bg-slate-50"><td class="px-5 py-4"><Link :href="`/inventory/${item.id}`" class="font-semibold text-slate-950 hover:text-emerald-700">{{item.variant?.product?.title||'未关联商品'}}</Link><p class="mt-1 text-xs text-slate-400">{{item.variant?.title||`Inventory #${item.shopify_inventory_item_id}`}}</p></td><td class="px-5 py-4 font-mono text-slate-600">{{item.sku||'—'}}</td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="item.tracked?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'">{{item.tracked?'是':'否'}}</span></td><td class="px-5 py-4 text-lg font-semibold text-slate-950">{{item.available_total??0}}</td><td class="px-5 py-4">{{item.levels_count}}</td><td class="px-5 py-4 text-xs text-slate-500">{{date(item.synced_at)}}</td></tr></tbody></table></div><EmptyState v-else class="border-0 shadow-none" title="暂无库存数据" description="创建库存同步任务后，库存项目与地点会显示在这里。" icon="inventory"/></section><Pagination :links="inventory.links"/></div></AppLayout></template>
